WITH base AS (SELECT *, UPPER(channel) AS channel_upper, CASE WHEN status IN ('SHIPPED', 'RETURNED') THEN 'Core' ELSE 'Other' END AS status_group FROM orders WHERE shipping_fee <= 21), metrics AS (SELECT *, LEAD(discount, 1) OVER (PARTITION BY channel, customer_id ORDER BY order_date, id) AS next_discount, AVG(discount) OVER (PARTITION BY status, store_id ORDER BY shipping_fee, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS discount_avg_3 FROM base), base_orders AS (SELECT *, DATE_FORMAT(order_date, 'yyyy-MM-dd') AS order_date_label FROM metrics WHERE order_date >= TO_DATE('2023-04-10') AND channel IS NOT NULL) SELECT s.id, s.customer_id, s.store_id, s.channel, s.amount, s.discount, s.shipping_fee, s.channel_upper, s.next_discount, CASE WHEN channel RLIKE '^(partner|web)$' THEN 'OTHER_ZONE' WHEN channel RLIKE '^(mobile|store)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS channel_zone, (SELECT AVG(x.monthly_fee) FROM subscriptions x WHERE x.customer_id = s.customer_id) AS avg_subscription_monthly_fee FROM base_orders s ORDER BY store_id NULLS LAST;
